{"command": "[Console]::OutputEncoding=[System.Text.Encoding]::UTF8
$fail = [System.Collections.Generic.List[string]]::new()
function TryDel([string]$p){
  if(Test-Path -LiteralPath $p){
    try { Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction Stop; Write-Output "已删除: $p" }
    catch { Write-Output ("!! 失败: $p  ->  " + $_.Exception.Message); $fail.Add($p) }
  } else { Write-Output "未找到(跳过): $p" }
}
Write-Output "===== B. 缓存 ====="
TryDel '.tools\templates-official.zip'
TryDel 'LLM-tmp\.review'
TryDel 'LLM-tmp\客户端\.godot'
TryDel 'LLM-tmp\04-工具\pylibs'
Write-Output "===== C. 8 个临时目录 ====="
foreach($d in @('docx-review','docx-v9','docx-v9-final','docx-v9-plan-clean','docx-v9-plan-final','gameover-before','story-qa','v10-qa')){ TryDel ".tools\$d" }
Write-Output "===== C. 残留空目录与本机存档 ====="
TryDel 'LLM-tmp\服务端\LLM-tmp'
TryDel 'LLM-tmp\服务端\data\save.json'
TryDel 'output\imagegen\model-tests'
Write-Output ("失败项数量: " + $fail.Count)", "description": "Delete caches, temp dirs and residue"}

